/// path-gated skills (`paths:` frontmatter) join the prompt on the next
/// turn, and stamps [_toolStarts] for the end row's elapsed zone.
void _onToolExecutionStart(
  String toolCallId,
  String toolName,
  Map<String, dynamic> args,
