/// [CliIO] bound to the real terminal: stdin lines, stdout writes, and a
/// broadcast interrupt channel fed by the SIGINT handler in `main`.
///
/// In [headless] mode diagnostics ([writeln]) go to stderr so stdout carries
/// only the assistant text, input is never read, and the CLI is never
/// interactive (approval/ask prompts resolve non-interactively).
final class _TerminalCliIO implements CliIO {
  _TerminalCliIO({this.headless = false});

  /// Whether the CLI runs a single headless prompt.
  final bool headless;

  final _interrupts = StreamController<void>.broadcast();
  StreamController<KeyEvent>? _keyController;
  StreamSubscription<List<int>>? _keySub;
  var _rawModeOk = true;

  void fireInterrupt() => _interrupts.add(null);

  @override
  Stream<String> get lines => headless
      ? const Stream<String>.empty()
      : stdin.transform(utf8.decoder).transform(const LineSplitter());

  @override
  Stream<KeyEvent> get keys {
    if (headless || !supportsRawMode) return const Stream<KeyEvent>.empty();
    _keyController ??= StreamController<KeyEvent>.broadcast(
      onListen: _startRawInput,
      onCancel: _stopRawInput,
    );
    return _keyController!.stream;
  }

  @override
  Stream<void> get interrupts => _interrupts.stream;

  @override
  void write(String text) {
    // StreamTrace render mark (diagnostic, no-op unless active): the
    // headless / line-mode live surface — stdout. Same leg the TUI seam
    // records; exactly one of the two seams fires per surface write
    // (headless and line-mode REPL never construct _TuiCliIO, and the
    // TUI seam marks only its own sendOutput branch), so the emit→render
    // gap is measurable in bench/scripted runs too.
    StreamTrace.mark(StreamTraceMark.render, '+${text.length}ch');
    stdout.write(text);
  }

  @override
  void writeln(String text) =>
      headless ? stderr.writeln(text) : stdout.writeln(text);

  /// Piped input (no terminal) means no human can answer approval prompts:
  /// the CLI then denies prompt-policy tool calls with a reason. Headless
  /// mode is never interactive, terminal or not.
  @override
  bool get isInteractive => !headless && stdin.hasTerminal;

  @override
  bool get supportsRawMode => !headless && stdin.hasTerminal && _rawModeOk;

  @override
  int get columns {
    // stdout can be a pipe (session switch replay, headless-ish paths) —
    // terminalColumns throws StdoutException there (crash.log had two).
    try {
      return stdout.terminalColumns;
    } on StdoutException {
      return 80;
    }
  }

  @override
  int get rows {
    try {
      return stdout.terminalLines;
    } on StdoutException {

      _style.dim(
        '[message cap] provider refused the request at '
        '${event.messageCount} messages'
        '${event.learnedCap == null ? '' : ' (cap ${event.learnedCap})'}'
        '${event.compacted ? ' — context compacted, retrying once' : ' — coalescing the request, retrying once'}',
      ),
    );
  }
  await handleAgentEvent(
    event,
    onMessageLifecycle: _onMessageLifecycle,
    onMessageUpdate: _onMessageUpdate,
    onToolExecutionStart: _onToolExecutionStart,
    onToolExecutionEnd: _onToolExecutionEnd,
    onTurnEnd: (message) {
      _usage.add(message.usage);
      // gh-1762: the provider's real output tokens recalibrate the
      // char→token factor for the next message's live estimate (AC4).
      _meter.calibrate(message.usage.output);
    },
    onModelRequest: _onModelRequest,
    onTaskLedger: _onTaskLedger,
  );
}

/// fa.log forensics for the phase-transition events (the plain
/// diagnostic cases of [_onAgentEvent]; the record-persisting cases
/// live in [_persistEventLiveness] — split to keep both sides under
/// the crap4dart CRAP ceiling, gh-1449 rework round 3).
void _logEventForensics(AgentEvent event) {
  switch (event) {
    case AgentStartEvent():
      _logDiagnostic('run start sid=$_logSid');
    case TurnStartEvent():
      _logDiagnostic('turn start sid=$_logSid');
    case ToolExecutionStartEvent(:final toolName):
      _logDiagnostic('tool start sid=$_logSid name=$toolName');
    case ToolExecutionEndEvent(:final toolName, :final isError):
      _logDiagnostic('tool end sid=$_logSid name=$toolName error=$isError');
    case TurnEndEvent(:final message):
      _logDiagnostic('turn end sid=$_logSid stop=${message.stopReason.name}');
    case AgentEndEvent():
      _logDiagnostic('run end sid=$_logSid');
    default:
    // The record-persisting cases (tool-call heartbeats, stuck calls,
    // pairing repairs, message-cap repairs) log where the record is
    // written (see [_persistEventLiveness]) — nothing extra here.
  }
}

/// Session-record side of the liveness events (heartbeats, stuck calls,
/// orphan-report batches): each case logs its own diagnostic line so the
/// original intra-event order (log → persist → terminal print) is
/// preserved.
Future<void> _persistEventLiveness(AgentEvent event) async {
  switch (event) {
    case ToolCallHeartbeatEvent(
      :final toolCallId,
      :final toolName,
      :final args,
      :final elapsed,
      :final outputBytes,
      :final attempt,
    ):
      // Liveness heartbeat (gh-1054): the session record keeps the trace
      // fresh for external watchers; the terminal stays quiet (the busy
      // row already names the running tool).
      _logDiagnostic(
        'tool heartbeat sid=$_logSid name=$toolName '
        'elapsed=${elapsed.inSeconds}s out=${outputBytes}B '
        'attempt=$attempt',
      );
      await _persistToolLivenessRecord(toolHeartbeatRecordType, {
        'tool': toolName,
        'toolCallId': toolCallId,
        'elapsedMs': elapsed.inMilliseconds,
        'outputBytes': outputBytes,
        'attempt': attempt,
        'args': _stuckArgsSummary(args),
      });
    case ToolCallStuckEvent(
      :final toolCallId,
      :final toolName,
      :final elapsed,
      :final action,
      :final detail,
    ):
      _logDiagnostic(
        'tool stuck sid=$_logSid name=$toolName action=${action.name} '
        'elapsed=${elapsed.inSeconds}s',
      );

