/// gh-1931 — one render per tool call on every console surface.
///
/// The non-TUI console (line mode + headless log) printed every executed
/// tool call TWICE: a start row (`• label · detail`, no elapsed) from
/// `_onToolExecutionStart` followed by an end row (`✓/✗ label · detail
/// Ns`) from `_onToolExecutionEnd`. The end row already carries everything
/// the start row said (detail = command, status glyph, elapsed; failure
/// text on error), so the start row was a pure duplicate print — the bug
/// YuryBY reported ("a tool row with elapsed time plus a redundant second
/// print without it").
///
/// These tests pin the fix at the byte level:
/// - AC1 line mode: command string once, elapsed marker once (golden).
/// - AC3 headless: new log == OLD log minus ONLY the duplicated start rows
///   (no new losses, no reordering) — command, status, elapsed, failure
///   marker each exactly once.
/// - AC4 success AND failure paths single-rendered; the `!cmd` local-exec
///   branch stays single-rendered.
/// - AC2 the TUI keeps its running card (the transcript grammar is a
///   non-goal — the dedupe must not leak past the non-TUI branch).
/// - AC5 the session JSONL keeps the full call + result records.
/// - E1/E2/E4: multi-line command truncated once, background job settle
///   notices survive, empty-output calls still render exactly one row.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
// LocalExecutionEnv is a VM-only surface (dart:io-backed) — it ships via
// the io.dart barrel, not the platform-neutral one.
import 'package:flutter_agent_harness/io.dart';
import 'package:flutter_agent_harness/src/cli/tool_rows.dart';
import 'package:flutter_agent_harness/src/cli/tui_chrome.dart';
import 'package:flutter_agent_harness/src/cli/tui_repl.dart';
import 'package:flutter_agent_harness/src/cli/tui_theme.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

/// The unpainted console row the non-TUI surface prints (no theme profile
/// in tests → `tuiToolRow` returns `│ ${row.join()}`).
String _row(ToolRowSegments segments, ToolRowState state) =>
    tuiToolRow(layoutToolRow(segments, -2), state);

/// The tool-row lines of a captured console/log channel. Line mode prints
/// the first row after the `fa> ` prompt on the same physical line — the
/// prompt prefix is stripped so the row bytes compare exactly.
List<String> _rowLines(String channel) => channel
    .split('\n')
    .map(
      (line) => line.startsWith('fa> ') ? line.substring('fa> '.length) : line,
    )
    .where((line) => line.startsWith('│ '))
    .toList();

AgentCli _cli(
  CliIO io, {

    _onAssistantMessageEnd(message);
  }

  /// Tool start row in the compact grammar (issue #366): `• label ·
  /// detail` — the human detail (question text, command, path), never the
  /// raw args JSON. Also records file-path args into [_touchedPaths] so
  /// path-gated skills (`paths:` frontmatter) join the prompt on the next
  /// turn, and stamps [_toolStarts] for the end row's elapsed zone.
  void _onToolExecutionStart(
    String toolCallId,
    String toolName,
        ),
      );
    }
  }

  /// Tool end row in the compact grammar (issue #366): `✓ label · detail
  /// Ns` — the same detail the start row showed, plus the elapsed; errors
  /// render `✗` with the result's first line as a full-bright snippet (the
  /// one place the muted detail role gives way to readability).
  void _onToolExecutionEnd(
    String toolCallId,
    String toolName,
    ToolExecutionResult result, {
    required bool isError,
  }) {
    final (started, startDetail) = _toolStarts.remove(toolCallId) ?? (null, '');
    _waiting.toolCallEnded(toolCallId);
    // No offer may outlive its call (issue #1786): the call ending is the
    // last chance to clear a stale outstanding `b` affordance.
    budgetOfferCleared();
    final elapsed = started == null
        ? ''
        : '${DateTime.now().difference(started).inSeconds}s';
    final state = isError ? ToolRowState.failed : ToolRowState.done;
    // TUI chrome (issue #807): the settled card carries the phase tint
    // (success/error), the elapsed meta, and — on failure — the bright
    // first line of the failure text as the news. The SAME builder the
    // replay paints ([settledToolCardRows], issue #916) — parity by
    // construction. Line mode and headless keep the legacy row
    // byte-identically.
    if (_useTui && tuiChromeEnabled) {
      io.writeln(
        settledToolCardRows(
          toolName: toolName,
          successDetail: startDetail,
          isError: isError,
          width: _rowWidth,
          resultContent: result.content,
          meta: [elapsed],
        ).join('\n'),
      );
/// The restored-transcript renderer (issue #446): ONE pipeline for live and
/// replayed history. Every row type the live TUI draws is drawn here by the
/// SAME builder — tool rows through the live end-row grammar ([tuiToolCard]
/// band chrome since #807, [layoutToolRow] under the chrome kill switch,
/// [toolRowDetail] for the detail), system notices through
/// [renderSystemNoticeLines], assistant text as raw markdown the view
/// styles at render time — so a reopened session looks exactly like the
/// moment the terminal was closed (issue #916: the replay rides the same
/// chrome migration as the live edge by default — the `tuiChromeEnabled`
/// kill switch and line mode intentionally keep the legacy row,
/// byte-pinned).
///
/// The only permitted live/replay difference is honest lossy bits: replayed
/// tool rows carry no live durations (the `—` elapsed meta where a live
/// card shows `3s`) and spinners never render from replay.

/// A code-fence opener/closer line (```). Tracked by the replay so a
/// truncated message never leaves a dangling fence: the view formats the
/// whole history as ONE markdown stream, and an unclosed fence would render
/// everything after it as verbatim code (raw `**`, tables, links).
final _fenceLineRe = RegExp(r'^\s*```');

arguments.newText:
/// Tool-call start bookkeeping (issue #366 grammar): records file-path
/// args into [_touchedPaths] so path-gated skills (`paths:` frontmatter)
/// join the prompt on the next turn, stamps [_toolStarts] for the end
