      ]),
    );
    final run = cli.run();
    io.sendLine('run a failing bash call');
    await waitForIt(
      () => io.out.toString().contains('done'),
      reason: 'the turn settled with the final text',
    );

    final rows = _rowLines(io.out.toString());
    expect(rows, [
