        const ToolRowSegments(
          glyph: '✗',
          label: 'bash',
          detail: 'Tool error (bash): boom-out',
          elapsed: '0s',
        ),
        ToolRowState.failed,
      ),
    ], reason: '--- console output ---\n${io.out}');
    expect(io.out.toString().contains('│ • '), isFalse);

    await run.timeout(const Duration(seconds: 10), onTimeout: () {});
    await io.close();
  },
);

